 pcoverage(pair_count,points.size());fs_reject([&]{pcoverage(pair_count-1,points.size());});size_t pair_lines=lines.size(),tangent_count=0,flex_tangents=0;
 for(size_t i=0;i<points.size();++i){const auto&p=points[i];F fx=fs_eval(c.partial(0),p.x,p.y),fy=fs_eval(c.partial(1),p.x,p.y);require(fx!=F(0)||fy!=F(0),"smooth old tangent");PL line=pnormalize({fx,fy,-fx*p.x-fy*p.y});auto q=ss_restrict(c,p.x,p.y,line[1],-line[0]);require(q.degree()==4&&q.at(0)==F(0)&&q.at(1)==F(0),"exact smooth tangent restriction");int m=2;while(m<=4&&q.at(m)==F(0))++m;require(m<=4,"proper tangent contact");insert(line).support[int(i)]=m;++tangent_count;if(m>=3)++flex_tangents;}
 require(tangent_count==points.size(),"all old tangents included");
