 auto matrix=sc_read_matrix(tangents.at("matrix"));require(sc_rank(matrix)==108,"original full rank");for(auto&row:matrix)row.resize(columns.size());for(const auto&proof:proofs){SCRow row(columns.size());std::copy(proof.old_row.begin(),proof.old_row.end(),row.begin());if(proof.residual_column>=0)row[size_t(proof.residual_column)]+=proof.residual_sign;matrix.push_back(std::move(row));}
